#[test]
fn check_oniguruma_mode_changes_wordbounds() {
    fn find_all_matches(regex: &Regex, text: &'static str) -> Vec<&'static str> {
        regex.find_iter(text).map(|m| m.unwrap().as_str()).collect()
    }

    let pattern = r"\<prefix_\w*\>";
    let test_text = "not_prefix_oops prefix_with_suffix <prefix_>";

    // By default the pattern is interpretted as a left word-bound followed by the literal "prefix_"
    // followed by any number of word characters ending on a right word-bound
    let default_mode = Regex::new(pattern).unwrap();
    let default_matches = find_all_matches(&default_mode, test_text);
    assert_eq!(default_matches, ["prefix_with_suffix

[ \t]+").unwrap();
    /// let target = "a b \t  c\td    e";
    /// let fields: Vec<&str> = re.splitn(target, 3).map(|x| x.unwrap()).collect();
    /// assert_eq!(fields, vec!["a

\A(foo)\z")
        .allow_input_assertion_overrides(true)
        .build()
        .unwrap();
    let re_bytes = RegexBuilder::new(r"\A(foo)\z")
        .bytes_mode(BytesMode::Ascii)
        .allow_input_assertion_overrides(true)
        .build()
        .unwrap();
    let caps = re
        .captures_input(RegexInput::new("foo").start_text(false).end_text(false))
        .unwrap();
    assert!(caps.is_none());
    let caps = re_bytes
        .captures_input(
            RegexInput::new("foo".as_bytes())
                .start_text(false)
                .end_text(false),
        )
        .unwrap();
    assert!(caps.is_none());

    let caps = re
        .captures_input(RegexInput::new("foo").start_text(true).end_text(true))
        .unwrap()
        .unwrap();
    assert_match(caps.get(0), "foo", 0, 3);
    assert_match(caps.get(1), "foo", 0, 3);

    let caps = re_bytes
        .captures_input(
            RegexInput::new("foo".as_bytes())
                .start_text(true)
                .end_text(true),
        )
        .unwrap()
        .unwrap();
    assert_eq!(caps.get(0).map(|m| (m.start(), m.end())), Some((0, 3)));
    assert_eq!(caps.get(1).map(|m| (m.start(), m.end())), Some((0, 3)));
}

