#[test]
fn oniguruma_plus_after_quantifier() {
    let re = RegexBuilder::new("^x{2}+$")
        .oniguruma_mode(true)
        .build()
        .unwrap();
    let result = re.find_from_pos("xxxx", 0).unwrap();
    assert!(result.is_some(), "quantifier should be repeated");

    let re = RegexBuilder::new("^x{0,3}+$")
        .oniguruma_mode(true)
        .build()
        .unwrap();
    let result = re.find_from_pos("xx", 0).unwrap();
    assert!(result.is_some(), "quantifier should be repeated");
}

#[test]
fn find_from_pos_startline_rejected_after_trailing_newline_at_eof() {
    let re = RegexBuilder::new("^")
        .oniguruma_mode(true)
        .multi_line(true)
        .build()
        .unwrap();
    let result = re.find_from_pos("ab\n", 3).unwrap();
    assert!(
