#[test]
fn backtrack_limit_hit_when_not_seeking() {
    // Disable the seek pre-filter so the backtracking VM actually explores all positions and
    // hits the limit.  With seek enabled the engine would correctly determine there is no `c`
    // in the haystack and return `None` immediately without backtracking.
    let re = RegexBuilder::new(r"(?i)(a|b|ab)*(?>c)")
        .backtrack_limit(100_000)
        .seek(false)
        .build()
        .expect("regex to compile successfully");
    let s = "abababababababababababababababababababababababababababab";
    let result = re.is_match(s);
    assert!(result.is_err());
    match result.err() {
        Some(Error::RuntimeError(RuntimeError::BacktrackLimitExceeded)) => {}
        _ => panic!("Expected RuntimeError::BacktrackLimitExceeded"),
    }

    // The same behaviour must hold in bytes mode.
    let re = RegexBuilder::new(r"(?i)(a|b|ab)*(?>c)")
        .bytes_mode(BytesMode::Ascii)
        .backtrack_limit(100_000)
        .build()
        .expect("regex to compile successfully");
    let s = b"abababababababababababababababababababababababababababab";
    let result = re.is_match(s);
    assert!(result.is_err());
    match result.err() {
        Some(Error::RuntimeError(RuntimeError::BacktrackLimitExceeded)) => {}
        _ => panic!("Expected RuntimeError::BacktrackLimitExceeded"),
    }
}

#[test]
fn backtrack_limit_not_applicable_when_seeking() {
    // Enable the seek pre-filter so the backtracking VM would only explore all positions
    // which could match.  With seek enabled the engine will correctly determine there is no `c`
    // in the haystack and return `None` immediately without backtracking.
    let re = RegexBuilder::new(r"(?i)(a|b|ab)*(?>c)")
        .backtrack_limit(1)
        .seek(true)
        .build()
        .expect("regex to compile successfully");
    let s = "abababababababababababababababababababababababababababab";
    let result = re.is_match(s);
    assert!(result.is_ok());
    assert!(!result.unwrap());
}

#[test]
fn can_find_matches_when_seeking() {
    let re = RegexBuilder::new(r"(abc|def)\1")
        .seek(true)
        .build()
        .expect("regex to compile successfully");
    let s = "abcdefabcdefabcdefdef";
    let result = re.is_match(s);
    assert!(result.is_ok());
    assert!(result.unwrap());
}

#[test]
fn end_of_hard_expression_cannot_be_delegated() {
    common::assert_is_match(r"(?!x)(?:a|ab)c

\b{1}"),
            Expr::Repeat {
                child: Box::new(Expr::Assertion(Assertion::WordBoundary)),
                lo: 1,
                hi: 1,
                greedy: true
            }
        );
        assert_eq!(
            p(r"\B{2}"),
            Expr::Repeat {
                child: Box::new(Expr::Assertion(Assertion::NotWordBoundary)),
                lo: 2,
                hi: 2,
                greedy: true
            }
        );
        assert_eq!(
            p(r"^{3}"),
            Expr::Repeat {
                child: Box::new(Expr::Assertion(Assertion::StartText)),
                lo: 3,
                hi: 3,
                greedy: true
            }
        );
        assert_eq!(
            p(r"${1,5}"),
            Expr::Repeat {
                child: Box::new(Expr::Assertion(Assertion::EndText)),
                lo: 1,
                hi: 5,
                greedy: true
            }
        );
        assert_eq!(
            p(r"\A*"),
            Expr::Repeat {
                child: Box::new(Expr::Assertion(Assertion::StartText)),
                lo: 0,
                hi: usize::MAX,
                greedy: true
            }
        );
        assert_eq!(
            p(r"\z+"),
            Expr::Repeat {
                child: Box::new(Expr::Assertion(Assertion::EndText)),
                lo: 1,
                hi: usize::MAX,
                greedy: true
            }
        );
        assert_eq!(
            p(r"^?"),
            Expr::Repeat {
                child: Box::new(Expr::Assertion(Assertion::StartText)),
                lo: 0,
                hi: 1,
                greedy: true
            }
        );
        assert_eq!(
            p(r"${2}"),
            Expr::Repeat {
                child: Box::new(Expr::Assertion(Assertion::EndText)),
                lo: 2,
                hi: 2,
                greedy: true
            }
        );
        assert_eq!(
            p(r"(?m)^?"),
            Expr::Repeat {
                child: Box::new(Expr::Assertion(Assertion::StartLine { crlf: false })),
                lo: 0,
                hi: 1,
                greedy: true
            }
        );
        assert_eq!(
            p(r"(?m)${2}"),
            Expr::Repeat {
                child: Box::new(Expr::Assertion(Assertion::EndLine { crlf: false })),
                lo: 2,
                hi: 2,
                greedy: true
            }
        );
        assert_eq!(
            p(r"\b+"),
            Expr::Repeat {
                child: Box::new(Expr::Assertion(Assertion::WordBoundary)),
                lo: 1,
                hi: usize::MAX,
                greedy: true
            }
        );
    }

    #[test]
    fn delegate_zero() {
        assert_eq!(p("\\b"), Expr::Assertion(Assertion::WordBoundary),);
        assert_eq!(p("\\B"), Expr::Assertion(Assertion::NotWordBoundary),);
    }

    #[test]
    fn delegate_named_group() {
        assert_eq!(
            p("\\p{Greek}"),
            Expr::Delegate {
                inner: String::from("\\p{greek}"),
                casei: false,
            }
